'use strict';
const $=id=>document.getElementById(id),Store=window.VaultStore;
const FIXED_TAGS=['读书笔记','灵感碎片','学习笔记','生活感悟'];
const TAG_COLORS={'读书笔记':'#10b981','灵感碎片':'#8b5cf6','学习笔记':'#f59e0b','生活感悟':'#f43f5e'};
function orderedTags(counts={}){return [...FIXED_TAGS.map(tag=>[tag,counts[tag]||0]),...Object.entries(counts).filter(([tag])=>!FIXED_TAGS.includes(tag)).sort((a,b)=>b[1]-a[1])];}
const state={online:false,view:'all',tag:'',categoryId:'',collapsedCategories:new Set(),q:'',filterTags:[],filterFrom:'',filterTo:'',filterMedia:'',filterUntagged:false,sort:'updated-desc',page:1,total:0,limit:24,layout:localStorage.getItem('kb-layout')||'card',items:[],stats:null,editing:null,draftId:null,detail:null,selectedMedia:null,saving:false,editRevision:0,lastSavedRevision:0,ready:false};
let syncTask=null,loadToken=0,draftTimer,autoTimer,toastTimer,pendingImport=null,lastRange=null;
const uid=()=>crypto.randomUUID?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join(''),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const formatDate=s=>{try{return new Intl.DateTimeFormat('zh-CN',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(s));}catch{return '';}};
function categoryNodes(){return state.stats?.categories||[];}
function categoryPath(id){const byId=new Map(categoryNodes().map(node=>[node.id,node]));const names=[];let node=byId.get(id);while(node){names.unshift(node.name);node=byId.get(node.parentId);}return names;}
function categoryPathText(id){return categoryPath(id).join(' / ');}
function categoryDescendantIds(id){const nodes=categoryNodes(),ids=[id];for(let i=0;i<ids.length;i++)for(const node of nodes)if(node.parentId===ids[i])ids.push(node.id);return ids;}
function renderCategoryTree(s){
 const nodes=s.categories||[],counts=s.categoryCounts||{};
 function branch(parentId){return nodes.filter(node=>node.parentId===parentId).map(node=>{
   const children=nodes.some(child=>child.parentId===node.id),expanded=!state.collapsedCategories.has(node.id);
   return `<div class="category-row depth-${node.depth}"><button class="category-toggle" data-expand-category="${esc(node.id)}" aria-label="${children?(expanded?'收起':'展开'):'无下级'} ${esc(node.name)}" ${children?'':'disabled'}>${children?(expanded?'▾':'▸'):'·'}</button><button class="nav category-item ${state.categoryId===node.id?'active':''}" data-category="${esc(node.id)}"><span class="tag-name">${esc(node.name)}</span><span>${counts[node.id]||0}</span></button>${node.depth<3?`<button class="category-add" data-add-child="${esc(node.id)}" aria-label="在${esc(node.name)}下新增子类">＋</button>`:''}</div>${children&&expanded?branch(node.id):''}`;
 }).join('');}
 const names=new Set(nodes.map(node=>node.name));
 const loose=orderedTags(s.tags||{}).filter(([name,count])=>count&&!names.has(name));
 return branch(null)+(loose.length?'<div class="nav-label">其他标签</div>'+loose.map(([tag,count])=>`<button class="nav ${state.tag===tag?'active':''}" data-tag="${esc(tag)}"><span class="tag-name">${esc(tag)}</span><span>${count}</span></button>`).join(''):'');
}
function categoryOptions(){return '<option value="">不分类</option>'+categoryNodes().map(node=>`<option value="${esc(node.id)}">${esc(categoryPathText(node.id))}</option>`).join('');}
function hideCategoryContextMenu(){const menu=$('categoryContextMenu');menu.hidden=true;delete menu.dataset.parentId;}
function showCategoryContextMenu(event){
 const row=event.target.closest('.category-row');if(!row||!$('tags').contains(row))return;
 const id=row.querySelector('[data-category]')?.dataset.category,node=categoryNodes().find(item=>item.id===id);if(!node)return;
 event.preventDefault();const menu=$('categoryContextMenu'),create=$('categoryContextCreate');
 menu.dataset.parentId=node.id;$('categoryContextTitle').textContent=categoryPathText(node.id);
 create.disabled=node.depth>=3;create.textContent=create.disabled?'已到第三级，不能再建下级':`新建${node.depth+1}级目录`;
 menu.hidden=false;const bounds=menu.getBoundingClientRect();
 menu.style.left=Math.max(8,Math.min(event.clientX,innerWidth-bounds.width-8))+'px';
 menu.style.top=Math.max(8,Math.min(event.clientY,innerHeight-bounds.height-8))+'px';
 if(!create.disabled)create.focus();
}
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4500);}
const sidePane=()=>matchMedia('(min-width: 1200px)').matches;
function showPane(dialog){const overlay=dialog.id==='editorDialog'&&dialog.classList.contains('editor-overlay');if(!dialog.open){if(sidePane()&&!overlay)dialog.show();else dialog.showModal();}document.body.classList.toggle('pane-open',sidePane()&&!overlay);}
function hidePane(dialog){if(dialog.open)dialog.close();if(dialog.id==='editorDialog')dialog.classList.remove('editor-overlay');document.body.classList.toggle('pane-open',sidePane()&&($('editorDialog').open||$('detailDialog').open));if(dialog.id==='editorDialog')document.body.classList.remove('focus-mode');}
function selectedTags(){return $('editTags').value.split(/[,，]/).map(t=>t.trim()).filter(Boolean);}
function updateQuickTags(){const selected=new Set(selectedTags());$('quickTags').querySelectorAll('[data-quick-tag]').forEach(button=>button.setAttribute('aria-pressed',String(selected.has(button.dataset.quickTag))));}
function renderSearchFilters(){const counts=state.stats?.tags||{},names=[...new Set([...FIXED_TAGS,...state.filterTags,...orderedTags(counts).map(([tag])=>tag)])].slice(0,Math.max(20,FIXED_TAGS.length+state.filterTags.length));$('filterTags').innerHTML=names.map(tag=>`<button type="button" data-filter-tag="${esc(tag)}" aria-pressed="${state.filterTags.includes(tag)}">${esc(tag)}</button>`).join('');const active=state.filterTags.length+Number(!!state.filterFrom)+Number(!!state.filterTo)+Number(!!state.filterMedia)+Number(state.filterUntagged);$('filterCount').textContent=active?'· '+active+' 项已选':'';}
function highlight(value,term){const source=String(value||''),needle=String(term||'');if(!needle)return esc(source);const lower=source.toLocaleLowerCase(),search=needle.toLocaleLowerCase();let result='',start=0,at;while((at=lower.indexOf(search,start))!==-1){result+=esc(source.slice(start,at))+'<mark>'+esc(source.slice(at,at+needle.length))+'</mark>';start=at+needle.length;}return result+esc(source.slice(start));}
function plainExcerpt(html){return new DOMParser().parseFromString(String(html||''),'text/html').body.textContent.replace(/\s+/g,' ').trim();}
function listParams(){const params=new URLSearchParams({view:state.view,q:state.q,tag:state.tag,category:state.categoryId,sort:state.sort,page:state.page,limit:state.limit,from:state.filterFrom,to:state.filterTo,media:state.filterMedia,untagged:state.filterUntagged?'1':''});for(const tag of state.filterTags)params.append('tags',tag);return params;}
function matchesLocal(r){if((state.view==='trash'?!!r.deletedAt:!r.deletedAt)===false)return false;if(state.view==='favorites'&&!r.favorite)return false;if(state.tag&&!r.tags.includes(state.tag))return false;if(state.categoryId&&!categoryDescendantIds(state.categoryId).includes(r.categoryId))return false;if(state.filterTags.some(tag=>!r.tags.includes(tag)))return false;if(state.filterUntagged&&r.tags.length)return false;if(state.filterFrom&&r.updatedAt.slice(0,10)<state.filterFrom)return false;if(state.filterTo&&r.updatedAt.slice(0,10)>state.filterTo)return false;if(state.filterMedia==='image'&&!/<img\b/i.test(r.content||''))return false;if(state.filterMedia==='video'&&!/<video\b/i.test(r.content||''))return false;if(state.filterMedia==='none'&&/<(?:img|video)\b/i.test(r.content||''))return false;return !state.q||(r.title+' '+r.summary+' '+(r.content||'')).toLocaleLowerCase().includes(state.q.toLocaleLowerCase());}
function resetFilters(){state.q='';state.tag='';state.categoryId='';state.filterTags=[];state.filterFrom='';state.filterTo='';state.filterMedia='';state.filterUntagged=false;$('search').value='';$('filterFrom').value='';$('filterTo').value='';$('filterMedia').value='';$('filterUntagged').checked=false;renderSearchFilters();}
function mediaUrl(value){if(!value)return '';try{const url=new URL(value,location.origin);if(url.protocol==='http:'||url.protocol==='https:'||/^data:(image\/(png|jpeg|gif|webp|svg\+xml)|video\/(mp4|webm))(;base64)?,/i.test(value))return value;}catch{}return '';}
function sanitize(html){const source=new DOMParser().parseFromString(String(html||''),'text/html'),root=document.createElement('div');const tags=new Set(['P','DIV','SPAN','BR','B','STRONG','I','EM','U','S','STRIKE','H1','H2','H3','H4','UL','OL','LI','BLOCKQUOTE','PRE','CODE','A','IMG','VIDEO','SOURCE','HR','TABLE','THEAD','TBODY','TR','TH','TD']);const denied=new Set(['SCRIPT','STYLE','IFRAME','OBJECT','EMBED','SVG','MATH','TEMPLATE','FORM','INPUT','BUTTON','LINK','META']);
 function copy(node,parent){if(node.nodeType===3){parent.append(document.createTextNode(node.textContent));return;}if(node.nodeType!==1||denied.has(node.tagName))return;if(!tags.has(node.tagName)){for(const child of node.childNodes)copy(child,parent);return;}const el=document.createElement(node.tagName.toLowerCase());if(['IMG','VIDEO','SOURCE'].includes(node.tagName)){const url=mediaUrl(node.getAttribute('src'));if(!url&&node.tagName!=='VIDEO')return;if(url)el.setAttribute('src',url);if(node.tagName==='IMG'){el.alt=node.getAttribute('alt')||'';el.loading='lazy';}if(node.tagName==='VIDEO'){el.controls=true;el.preload='metadata';}}if(node.tagName==='A'){const href=node.getAttribute('href')||'';if(/^(https?:\/\/|mailto:)/i.test(href)){el.href=href;el.target='_blank';el.rel='noopener noreferrer';}}for(const prop of ['width','height']){const v=node.style[prop]||node.getAttribute(prop);if(v&&/^(auto|\d{1,4}(\.\d+)?(px|%)?)$/.test(v))el.style[prop]=/^\d+$/.test(v)?v+'px':v;}for(const prop of ['textAlign','fontWeight','fontStyle','textDecoration','color','backgroundColor']){const v=node.style[prop];if(v&&!/url|expression|var\(/i.test(v))el.style[prop]=v;}for(const child of node.childNodes)copy(child,el);parent.append(el);}for(const child of source.body.childNodes)copy(child,root);return root.innerHTML;}
async function api(url,options={}){let res;try{res=await fetch(url,{...options,signal:options.signal||AbortSignal.timeout(12000),headers:{...(options.body&&!options.binary?{'Content-Type':'application/json'}:{}),...options.headers}});}catch(error){state.online=false;connection();throw error;}if(!res.ok){const data=await res.json().catch(()=>({}));const error=new Error(data.error||`请求失败 (${res.status})`);error.status=res.status;if(res.status===401)showLogin();throw error;}state.online=true;connection();return res.json();}
function connection(){const pending=state.pending||0;$('syncStatus').textContent=!state.online?'离线 · 待连接':pending?`${pending} 项待同步`:'已连接资料库';$('syncStatus').classList.toggle('warning',!state.online||pending>0);}
async function queueState(){const queue=await Store.all('queue');state.pending=queue.length;connection();const blocked=queue.filter(q=>q.error);$('queueBanner').hidden=!queue.length;if(queue.length)$('queueBanner').innerHTML=`<span>${blocked.length?`${blocked.length} 项需要处理，其余修改仍在本地`:`${queue.length} 项修改已保存在此浏览器，等待写入资料库`}</span><button data-action="${blocked.length?'conflicts':'sync'}">${blocked.length?'处理冲突 / 错误':'立即重试'}</button>`;return queue;}
async function sync(){if(syncTask)return syncTask;syncTask=(async()=>{const queue=(await Store.all('queue')).sort((a,b)=>a.createdAt-b.createdAt),blocked=new Set();for(const op of queue){if(blocked.has(op.recordId)||op.error){blocked.add(op.recordId);continue;}try{const saved=await api('/api/operations',{method:'POST',body:JSON.stringify({opId:op.id,action:op.action,id:op.recordId,record:op.record,baseVersion:op.baseVersion})});await Store.remove('queue',op.id);const later=(await Store.all('queue')).some(q=>q.recordId===op.recordId);if(!later)await Store.put('records',saved);}catch(error){if([409,400,404].includes(error.status)){op.error=error.message;op.conflict=error.status===409;await Store.put('queue',op);blocked.add(op.recordId);}else break;}}await queueState();})().finally(()=>{syncTask=null;});return syncTask;}
async function cacheItems(items){const pending=new Set((await Store.all('queue')).map(q=>q.recordId));for(const item of items){if(pending.has(item.id))continue;const old=await Store.get('records',item.id);const content=old&&old.version===item.version?old.content:undefined;await Store.put('records',{...item,...(content!==undefined?{content}:{})});}}
async function refreshStats(){try{state.stats=await api('/api/stats');await Store.put('meta',{id:'stats',value:state.stats});}catch{state.stats=(await Store.get('meta','stats'))?.value||{count:0,favorites:0,week:0,tags:{},trash:0};}const s=state.stats;$('countAll').textContent=s.count;$('countFav').textContent=s.favorites;$('countTrash').textContent=s.trash;$('summary').innerHTML=`共 <b>${s.count}</b> 条记录 · 本周新增 <b>${s.week}</b> 条${!state.online?' · 离线显示已缓存内容':''}`;$('tags').innerHTML=renderCategoryTree(s);renderSearchFilters();}
async function loadList(){const token=++loadToken;$('records').innerHTML='<div class="empty">正在读取记录…</div>';let result;try{result=await api('/api/records?'+listParams());await cacheItems(result.items);if((await Store.all('queue')).length)result=null;}catch{result=null;}if(!result){let items=await Store.all('records');items=items.filter(matchesLocal);items.sort((a,b)=>state.sort==='title-asc'?a.title.localeCompare(b.title,'zh-CN'):state.sort==='updated-asc'?a.updatedAt.localeCompare(b.updatedAt):(state.sort==='created-desc'?b.createdAt.localeCompare(a.createdAt):b.updatedAt.localeCompare(a.updatedAt)));result={total:items.length,items:items.slice((state.page-1)*state.limit,state.page*state.limit)};}if(token!==loadToken)return;state.total=result.total;state.items=result.items;if(!result.items.length&&state.page>1){state.page--;return loadList();}renderList();}
function renderList(){const titles={all:'全部记录',recent:'最近更新',favorites:'收藏夹',trash:'回收站'};$('viewTitle').textContent=state.categoryId?categoryPathText(state.categoryId):state.tag||titles[state.view];$('filterLabel').textContent=`${state.q?`搜索“${state.q}” · `:''}${state.total} 条${!state.online?'已缓存记录（未缓存内容需连接后查看）':''}`;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',!state.tag&&!state.categoryId&&b.dataset.view===state.view));document.querySelectorAll('[data-layout]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.layout===state.layout)));$('records').className='records '+state.layout;if(!state.items.length){const filtered=state.q||state.tag||state.categoryId||state.filterTags.length||state.filterFrom||state.filterTo||state.filterMedia||state.filterUntagged,isTrash=state.view==='trash';$('records').innerHTML=`<div class="empty"><div class="symbol">${isTrash?'↶':'▤'}</div><h2>${filtered?'没有找到相关记录':isTrash?'回收站是空的':state.view==='favorites'?'还没有收藏':'记录从一个想法开始'}</h2><p>${filtered?'试试其他关键词，或清除筛选条件。':isTrash?'移除的记录会保留在这里，你可以随时恢复。':state.view==='favorites'?'将常用记录加入收藏，之后更容易找到。':'文字、图片、视频，都可以放在同一条记录里。'}</p>${filtered?'<button data-action="clear-filter">清除筛选</button>':!isTrash?'<button class="primary" data-action="new">＋ 创建第一条记录</button>':''}</div>`;}else $('records').innerHTML=state.items.map(r=>`<article class="card ${state.detail?.id===r.id||state.editing?.id===r.id?'selected':''}">${mediaUrl(r.cover)?`<img class="card-cover" src="${esc(mediaUrl(r.cover))}" alt="" loading="lazy">`:''}<div class="card-main"><button class="card-title" data-open="${esc(r.id)}">${highlight(r.title,state.q)}</button><p class="card-summary">${highlight(state.q&&r.matchExcerpt?plainExcerpt(r.matchExcerpt):r.summary||'暂无摘要',state.q)}</p><div class="chips">${r.categoryId?`<span class="chip">${esc(categoryPathText(r.categoryId))}</span>`:''}${r.tags.slice(0,4).map(t=>`<span class="chip">${esc(t)}</span>`).join('')}</div><div class="card-footer"><time datetime="${esc(r.updatedAt)}">${formatDate(r.deletedAt||r.updatedAt)}</time>${state.view==='trash'?`<button data-restore="${esc(r.id)}">恢复</button>`:`<button data-favorite="${esc(r.id)}" aria-label="${r.favorite?'取消收藏':'收藏'} ${esc(r.title)}" aria-pressed="${r.favorite}">${r.favorite?'★':'☆'}</button>`}</div></div></article>`).join('');$('pagination').hidden=state.total<=state.limit;$('pageLabel').textContent=`${state.page} / ${Math.max(1,Math.ceil(state.total/state.limit))}`;document.querySelector('[data-action="prev"]').disabled=state.page<=1;document.querySelector('[data-action="next"]').disabled=state.page*state.limit>=state.total;}
async function fullRecord(id){const local=await Store.get('records',id);if((await Store.all('queue')).some(q=>q.recordId===id)&&local?.content!==undefined)return local;try{const r=await api('/api/records/'+encodeURIComponent(id));await Store.put('records',r);return r;}catch(error){if(local?.content!==undefined)return local;throw new Error('这条记录的正文尚未缓存，请连接资料库后再查看。');}}
async function openDetail(id){try{if($('editorDialog').open&&!await closeEditor())return;const r=await fullRecord(id);state.detail=r;$('detailArticle').innerHTML=`<h1>${esc(r.title)}</h1><div class="muted">更新于 ${formatDate(r.updatedAt)}${r.deletedAt?' · 已在回收站':''}</div><div class="chips">${r.categoryId?`<span class="chip">${esc(categoryPathText(r.categoryId))}</span>`:''}${r.tags.map(t=>`<span class="chip">${esc(t)}</span>`).join('')}</div><div class="rich-content">${sanitize(r.content)}</div>`;$('detailFavorite').textContent=r.favorite?'★ 已收藏':'☆ 收藏';for(const action of ['favorite','edit-detail','delete-detail'])document.querySelector(`[data-action="${action}"]`).hidden=!!r.deletedAt;showPane($('detailDialog'));renderList();}catch(e){toast(e.message);}}
function draftContent(){return {id:state.draftId,recordId:state.editing?.id||null,base:state.editing,title:$('editTitle').value,content:sanitize($('content').innerHTML),tags:$('editTags').value,categoryId:$('editCategory').value||null,updatedAt:Date.now()};}
async function writeDraft(){if(!state.draftId)return;const draft=draftContent();if(!draft.title&&!draft.content&&!draft.tags)return;try{await Store.put('drafts',draft);$('draftState').textContent='草稿已保存在此浏览器 · '+new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'});await draftBanner();}catch{$('draftState').textContent='草稿保存失败，请勿关闭页面';toast('浏览器存储不足，请复制正文或释放空间后再保存。');throw new Error('草稿未保存');}}
function scheduleDraft(){state.editRevision++;$('draftState').textContent='正在保存…';$('wordCount').textContent=$('content').textContent.trim().length+' 字';updateQuickTags();clearTimeout(draftTimer);clearTimeout(autoTimer);draftTimer=setTimeout(()=>writeDraft().catch(()=>{}),450);autoTimer=setTimeout(()=>{if(!$('editorDialog').open)return;if(!$('content').textContent.trim()&&!$('content').querySelector('img,video')){$('draftState').textContent='草稿已留在浏览器，写入正文后自动保存';return;}saveEditor({auto:true});},1800);}
async function draftBanner(){const drafts=await Store.all('drafts');$('draftBanner').hidden=!drafts.length;$('draftBanner').querySelector('span').textContent=`有 ${drafts.length} 份未完成的草稿`;}
async function openEditor(r=null,draft=null){if($('editorDialog').open&&!await closeEditor())return;state.editing=r;state.draftId=draft?.id||(r?'record-'+r.id:'new-'+uid());if(!draft)draft=await Store.get('drafts',state.draftId);if(draft?.base)state.editing=draft.base;const creating=!state.editing;$('editorDialog').classList.toggle('editor-overlay',creating);$('closeEditor').textContent=creating?'关闭':'← 返回';$('editTitle').value=draft?.title??r?.title??'';$('content').innerHTML=sanitize(draft?.content??r?.content??'');$('editTags').value=draft?.tags??r?.tags?.join('，')??(state.view==='all'?state.tag:'');$('editCategory').innerHTML=categoryOptions();$('editCategory').value=draft?.categoryId??r?.categoryId??state.categoryId??'';$('editorHeading').textContent=creating?'新建记录':'编辑记录';$('draftState').textContent=draft?'已恢复草稿，准备自动保存':'修改后自动保存到本机';$('wordCount').textContent=$('content').textContent.trim().length+' 字';state.editRevision=0;state.lastSavedRevision=0;$('quickTags').innerHTML=orderedTags(state.stats?.tags||{}).slice(0,12).map(([t])=>`<button data-quick-tag="${esc(t)}">${esc(t)}</button>`).join('');updateQuickTags();selectMedia(null);if($('detailDialog').open)hidePane($('detailDialog'));if($('panelDialog').open)$('panelDialog').close();showPane($('editorDialog'));$('editTitle').focus();if(draft)scheduleDraft();}
async function closeEditor(){
  if(state.saving||state.uploading){toast('正在保存或上传，请稍候。');return false;}
  clearTimeout(draftTimer);clearTimeout(autoTimer);
  try{
    if(state.editRevision>state.lastSavedRevision){
      const hasContent=$('content').textContent.trim()||$('content').querySelector('img,video');
      if(hasContent){if(!await saveEditor({auto:true}))return false;}
      else await writeDraft();
    }
    hidePane($('editorDialog'));selectMedia(null);state.draftId=null;
    await draftBanner();renderList();return true;
  }catch(error){toast(error.message||'草稿未保存，请重试。');return false;}
}
async function externalize(html){const root=document.createElement('div');root.innerHTML=sanitize(html);for(const el of root.querySelectorAll('img,video,source')){const src=el.getAttribute('src')||'';if(/^data:(image\/(png|jpeg|gif|webp)|video\/(mp4|webm));base64,/i.test(src)&&state.online){try{const blob=await fetch(src).then(r=>r.blob());const result=await api('/api/attachments',{method:'POST',body:blob,binary:true,headers:{'Content-Type':'application/octet-stream'}});el.src=result.url;}catch{}}}return root.innerHTML;}
async function stage(action,r,baseVersion){const op={id:uid(),recordId:r.id,action,record:r,baseVersion,createdAt:Date.now()};await Store.enqueue(op,r);await queueState();await sync();return {pending:await Store.get('queue',op.id),record:await Store.get('records',r.id)};}
async function saveEditor({auto=false,close=false}={}){
  if(state.uploading){if(!auto)toast('附件正在上传，请稍候再保存。');return false;}
  if(state.saving){if(!auto)toast('正在保存，请稍候。');return false;}
  if(state.editing&&state.editRevision<=state.lastSavedRevision){
    if(close){hidePane($('editorDialog'));selectMedia(null);state.draftId=null;renderList();}
    return true;
  }
  state.saving=true;
  const revision=state.editRevision;
  $('saveEditor').disabled=true;
  $('draftState').textContent='正在保存到本机…';
  try{
    clearTimeout(draftTimer);clearTimeout(autoTimer);
    await writeDraft();
    const content=await externalize($('content').innerHTML),root=document.createElement('div');
    root.innerHTML=content;
    const text=root.textContent.trim();
    if(!text&&!root.querySelector('img,video'))throw new Error('请先写点内容或添加图片、视频。');
    const tags=selectedTags();
    if(tags.some(t=>t.length>60)||tags.length>30)throw new Error('最多 30 个标签，每个不超过 60 字。');
    const existing=state.editing,now=new Date().toISOString();
    const record={id:existing?.id||uid(),title:$('editTitle').value.trim()||text.split(/\n/)[0].slice(0,60)||'图片与视频记录',summary:text.replace(/\s+/g,' ').slice(0,180),content,tags:[...new Set(tags)],categoryId:$('editCategory').value||null,cover:root.querySelector('img')?.getAttribute('src')||null,favorite:existing?.favorite||false,createdAt:existing?.createdAt||now,updatedAt:now,version:existing?existing.version+1:1,deletedAt:null};
    const result=await stage(existing?'update':'create',record,existing?.version);
    state.editing=result.record||record;
    state.lastSavedRevision=revision;
    const previousDraftId=state.draftId;
    state.draftId='record-'+record.id;
    await Store.remove('drafts',previousDraftId);
    if(previousDraftId!==state.draftId)await Store.remove('drafts',state.draftId);
    $('draftState').textContent=result.pending?'已存浏览器 · 待同步':'已保存到本机 · '+new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'});
    await draftBanner();await refreshStats();await loadList();
    if(close){hidePane($('editorDialog'));selectMedia(null);state.draftId=null;renderList();}
    if(!auto)toast(result.pending?'已保存到浏览器，等待写入资料库。':'已保存到资料库');
    return true;
  }catch(error){
    $('draftState').textContent='保存失败 · 内容仍在草稿中';
    if(!auto)toast(error.message||'保存失败，编辑内容仍保留。');
    return false;
  }finally{
    state.saving=false;$('saveEditor').disabled=false;$('saveEditor').textContent='完成';
    if(state.editRevision>revision&&$('editorDialog').open){clearTimeout(autoTimer);autoTimer=setTimeout(()=>saveEditor({auto:true}),1200);}
  }
}
async function favorite(id){try{if($('editorDialog').open&&state.editing?.id===id&&!await closeEditor())return;const r=await fullRecord(id),version=r.version;r.favorite=!r.favorite;r.version++;r.updatedAt=new Date().toISOString();const result=await stage('update',r,version);toast(result.pending?'收藏更改已保存本地，待同步':'收藏已更新');if($('detailDialog').open)await openDetail(id);await refreshStats();await loadList();}catch(e){toast(e.message);}}
