async function conflicts(){const queue=await Store.all('queue'),ids=[...new Set(queue.filter(q=>q.error).map(q=>q.recordId))];let html='<p class="muted">你的修改仍保存在此浏览器。另存为副本会同时保留资料库中的版本。</p>';for(const id of ids){const r=await Store.get('records',id),error=queue.find(q=>q.recordId===id&&q.error);html+=`<div class="setting-section"><h3>${esc(r?.title||id)}</h3><p>${esc(error.error)}</p><button data-copy-conflict="${esc(id)}">将我的修改另存为副本</button><button data-retry-conflict="${esc(id)}">重试原操作</button></div>`;}panel('待处理的修改',html);}
