async function importPreview(event){const file=event.target.files[0];if(!file)return;try{if(file.size>95*1024*1024)throw new Error('备份超过 95MB，请使用使用说明中的文件夹恢复方式。');pendingImport=JSON.parse(await file.text());const result=await api('/api/import/preview',{method:'POST',body:JSON.stringify({backup:pendingImport})});$('importPreview').innerHTML=`<div class="banner" style="display:block"><p>共 ${result.total} 条，新增 ${result.added} 条，重复 ${result.conflicts} 条，附件 ${result.attachments} 个，自建类目 ${result.categories} 个。${result.verified?'校验通过。':'旧格式，无校验码。'}</p><label class="field">重复记录处理<select id="importMode"><option value="skip">保留现有记录，跳过重复项</option><option value="overwrite">用备份覆盖重复项（先自动备份）</option></select></label><button class="primary" data-action="import-confirm">确认导入</button></div>`;}catch(e){pendingImport=null;toast(e.message);}}
async function importConfirm(){try{if((await Store.all('queue')).length)throw new Error('请先处理尚未同步的修改，再导入备份。');if(!pendingImport)return;const result=await api('/api/import',{method:'POST',body:JSON.stringify({backup:pendingImport,mode:$('importMode').value})});pendingImport=null;$('panelDialog').close();toast(`导入完成：新增 ${result.added}，更新 ${result.updated}，跳过 ${result.skipped}`);await refreshStats();await loadList();}catch(e){toast(e.message);}}
