function rememberRange(){const sel=getSelection();if(sel.rangeCount&&$('content').contains(sel.anchorNode))lastRange=sel.getRangeAt(0).cloneRange();}
function restoreRange(){$('content').focus();if(lastRange&&$('content').contains(lastRange.commonAncestorContainer)){const sel=getSelection();sel.removeAllRanges();sel.addRange(lastRange);}}
function insertHTML(html){restoreRange();document.execCommand('insertHTML',false,sanitize(html));rememberRange();scheduleDraft();}
async function attach(files){state.uploading=(state.uploading||0)+1;for(const file of files){if(file.size>50*1024*1024){toast('单个附件不能超过 50MB。');continue;}if(!/^image\/(png|jpeg|gif|webp)$|^video\/(mp4|webm)$/.test(file.type)){toast('支持 PNG、JPEG、GIF、WebP、MP4 和 WebM。');continue;}try{let url;if(state.online){const result=await api('/api/attachments',{method:'POST',body:file,binary:true,headers:{'Content-Type':'application/octet-stream'}});url=result.url;}else{url=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});}insertHTML(file.type.startsWith('image/')?`<img src="${esc(url)}" alt="${esc(file.name)}" style="width:100%"><p><br></p>`:`<video controls src="${esc(url)}" style="width:100%"></video><p><br></p>`);await writeDraft();toast(state.online?'附件已添加':'附件已保存在草稿，联网保存时上传');}catch(e){toast(e.message||'附件添加失败');}}state.uploading--; $('attachment').value='';}
function selectMedia(el){if(state.selectedMedia)state.selectedMedia.classList.remove('selected-media');state.selectedMedia=el;$('mediaControls').hidden=!el;$('resizeHandle').hidden=!el;if(el){el.classList.add('selected-media');const percent=Math.round(el.getBoundingClientRect().width/$('content').clientWidth*100);$('mediaWidth').value=percent;$('mediaPercent').textContent=percent+'%';positionHandle();}}
function positionHandle(){const el=state.selectedMedia;if(!el)return;const rect=el.getBoundingClientRect();$('resizeHandle').style.left=(rect.right-8)+'px';$('resizeHandle').style.top=(rect.bottom-8)+'px';}
function setMediaWidth(value){if(!state.selectedMedia)return;value=Math.min(100,Math.max(10,value));state.selectedMedia.style.width=value+'%';state.selectedMedia.style.height='auto';$('mediaPercent').textContent=Math.round(value)+'%';$('mediaWidth').value=value;positionHandle();scheduleDraft();}
async function action(name){switch(name){case'menu':$('sidebar').classList.toggle('open');$('shade').hidden=!$('sidebar').classList.contains('open');break;case'new':await openEditor();break;case'theme':document.body.classList.toggle('dark');localStorage.setItem('knowledge_base_theme',document.body.classList.contains('dark')?'dark':'light');break;case'clear-filter':resetFilters();state.page=1;await loadList();await refreshStats();break;case'reset-filters':resetFilters();state.page=1;await loadList();await refreshStats();break;case'prev':state.page--;await loadList();break;case'next':state.page++;await loadList();break;case'sync':if(!state.ready){await boot();break;}await sync();await refreshStats();await loadList();if(!state.pending)toast(state.online?'资料库已连接，修改已同步':'无法连接，修改仍保存在此浏览器');break;case'add-category':showAddCategory();break;case'save-category':await saveCategory();break;case'settings':await settings();break;case'drafts':await showDrafts();break;case'conflicts':await conflicts();break;case'close-panel':$('panelDialog').close();break;case'close-detail':hidePane($('detailDialog'));state.detail=null;renderList();break;case'edit-detail':await openEditor(state.detail);break;case'history':await showHistory();break;case'focus-editor':document.body.classList.toggle('focus-mode');break;case'favorite':await favorite(state.detail.id);break;case'delete-detail':await trash(state.detail.id);break;case'pdf':window.print();break;case'backup':await backup();break;case'backup-directory':await backupToDirectory();break;case'set-backup-directory':await saveBackupDirectory();break;case'move-data-directory':await moveDataDirectory();break;case'import-pick':$('importFile').click();break;case'import-confirm':await importConfirm();break;case'legacy':await legacy();break;case'legacy-confirm':await legacyConfirm();break;case'local-export':{const queued=await Store.all('queue');const ids=[...new Set(queued.map(q=>q.recordId))];const records=[];for(const id of ids){const r=await Store.get('records',id);if(r)records.push(r);}download('待同步内容-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify({format:'knowledge-base',version:2,records,drafts:await Store.all('drafts')}));toast('本地内容已导出；已上传附件仍需保留原附件目录。');break;}case'login':await login();break;case'attach':rememberRange();$('attachment').click();break;case'link':{rememberRange();const href=prompt('输入完整链接（https://…）');if(href){if(!/^https?:\/\//i.test(href)){toast('请输入 http 或 https 链接');break;}restoreRange();if(getSelection().isCollapsed)insertHTML(`<a href="${esc(href)}">${esc(href)}</a>`);else{document.execCommand('createLink',false,href);scheduleDraft();}}break;}case'remove-media':state.selectedMedia?.remove();selectMedia(null);scheduleDraft();break;case'demo':await openEditor(null,{id:'new-'+uid(),title:'欢迎来到我的知识库',content:'<h2>从一个想法开始</h2><p>记录阅读摘录、学习笔记和灵感。选中文字设置格式，或添加图片和视频。</p><ul><li>保存后记录写入本机资料库。</li><li>关闭编辑器，草稿仍可继续编辑。</li><li>误删记录可从回收站恢复。</li></ul>',tags:'使用指南'});break;}}
$('tags').addEventListener('contextmenu',showCategoryContextMenu);
$('categoryContextCreate').addEventListener('click',()=>{const id=$('categoryContextMenu').dataset.parentId;if(!id)return;hideCategoryContextMenu();showAddCategory(id);});
document.addEventListener('pointerdown',event=>{if(!$('categoryContextMenu').contains(event.target))hideCategoryContextMenu();},true);
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!$('categoryContextMenu').hidden){event.preventDefault();event.stopImmediatePropagation();hideCategoryContextMenu();}else if((event.key==='ContextMenu'||event.shiftKey&&event.key==='F10')&&event.target.closest?.('.category-row')){const rect=event.target.getBoundingClientRect();showCategoryContextMenu({target:event.target,clientX:rect.left+20,clientY:rect.bottom,preventDefault:()=>event.preventDefault()});}},true);
document.addEventListener('click',async event=>{const b=event.target.closest('button');if(!b)return;try{if(b.dataset.action)await action(b.dataset.action);else if(b.dataset.view){state.view=b.dataset.view;state.tag='';state.categoryId='';state.page=1;if(state.view==='recent'){state.sort='updated-desc';$('sort').value=state.sort;}await loadList();$('sidebar').classList.remove('open');$('shade').hidden=true;await refreshStats();}else if(b.dataset.tag){state.tag=b.dataset.tag;state.categoryId='';state.view='all';state.page=1;await loadList();await refreshStats();$('sidebar').classList.remove('open');$('shade').hidden=true;}else if(b.dataset.category){state.categoryId=b.dataset.category;state.tag='';state.view='all';state.page=1;await loadList();await refreshStats();}else if(b.dataset.expandCategory){const id=b.dataset.expandCategory;state.collapsedCategories.has(id)?state.collapsedCategories.delete(id):state.collapsedCategories.add(id);$('tags').innerHTML=renderCategoryTree(state.stats);}else if(b.dataset.addChild){showAddCategory(b.dataset.addChild);}else if(b.dataset.filterTag){const tag=b.dataset.filterTag;state.filterTags=state.filterTags.includes(tag)?state.filterTags.filter(t=>t!==tag):[...state.filterTags,tag];state.page=1;renderSearchFilters();await loadList();}else if(b.dataset.layout){state.layout=b.dataset.layout;localStorage.setItem('kb-layout',state.layout);renderList();}else if(b.dataset.open)await openDetail(b.dataset.open);else if(b.dataset.historyVersion)await showHistoryVersion(b.dataset.historyVersion);else if(b.dataset.restoreVersion)await restoreVersion(b.dataset.restoreVersion);else if(b.dataset.favorite)await favorite(b.dataset.favorite);else if(b.dataset.restore)await trash(b.dataset.restore,true);else if(b.dataset.draft){const d=await Store.get('drafts',b.dataset.draft);await openEditor(d.base,d);}else if(b.dataset.copyConflict)await copyConflict(b.dataset.copyConflict);else if(b.dataset.retryConflict){for(const op of await Store.all('queue'))if(op.recordId===b.dataset.retryConflict){delete op.error;await Store.put('queue',op);}await sync();await conflicts();}else if(b.dataset.quickTag){const tags=selectedTags(),tag=b.dataset.quickTag;$('editTags').value=(tags.includes(tag)?tags.filter(t=>t!==tag):[...tags,tag]).join('，');scheduleDraft();}else if(b.dataset.command){restoreRange();document.execCommand(b.dataset.command,false,b.dataset.value||null);rememberRange();scheduleDraft();}}catch(e){toast(e.message);}});
$('search').addEventListener('input',()=>{clearTimeout(state.searchTimer);state.searchTimer=setTimeout(()=>{state.q=$('search').value.trim();state.page=1;loadList();},250);});$('sort').addEventListener('change',()=>{state.sort=$('sort').value;state.page=1;loadList();});$('shade').addEventListener('click',()=>{$('sidebar').classList.remove('open');$('shade').hidden=true;});
for(const [id,key] of [['filterFrom','filterFrom'],['filterTo','filterTo'],['filterMedia','filterMedia']])$(id).addEventListener('change',()=>{state[key]=$(id).value;state.page=1;renderSearchFilters();loadList();});$('filterUntagged').addEventListener('change',()=>{state.filterUntagged=$('filterUntagged').checked;state.page=1;renderSearchFilters();loadList();});
$('closeEditor').addEventListener('click',event=>{event.preventDefault();closeEditor();});$('editorDialog').addEventListener('cancel',event=>{event.preventDefault();closeEditor();});$('saveEditor').addEventListener('click',()=>saveEditor({close:true}));
for(const id of ['editTitle','editTags','editCategory','content'])$(id).addEventListener('input',scheduleDraft);$('attachment').addEventListener('change',e=>attach(e.target.files));$('content').addEventListener('keyup',rememberRange);$('content').addEventListener('mouseup',rememberRange);document.querySelector('.toolbar').addEventListener('mousedown',e=>{if(e.target.closest('button')){rememberRange();e.preventDefault();}});
$('content').addEventListener('paste',event=>{event.preventDefault();rememberRange();const files=[...event.clipboardData.files];if(files.length){attach(files);return;}const html=event.clipboardData.getData('text/html'),text=event.clipboardData.getData('text/plain');insertHTML(html||esc(text).replace(/\n/g,'<br>'));});$('content').addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('Files'))e.preventDefault();});$('content').addEventListener('drop',e=>{e.preventDefault();if(e.dataTransfer.files.length)attach(e.dataTransfer.files);});$('content').addEventListener('click',e=>selectMedia(e.target.closest('img,video')));$('mediaWidth').addEventListener('input',e=>setMediaWidth(Number(e.target.value)));
$('resizeHandle').addEventListener('pointerdown',e=>{e.preventDefault();const handle=$('resizeHandle');handle.setPointerCapture(e.pointerId);const left=state.selectedMedia.getBoundingClientRect().left;const move=event=>setMediaWidth((event.clientX-left)/$('content').clientWidth*100);const end=()=>{handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',end);};handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',end);});$('editorDialog').addEventListener('scroll',positionHandle);window.addEventListener('resize',positionHandle);
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'&&$('editorDialog').open){e.preventDefault();saveEditor({auto:false,close:false});}if(e.key==='Escape'&&sidePane()&&$('editorDialog').open&&!$('editorDialog').classList.contains('editor-overlay')&&!$('panelDialog').open){e.preventDefault();closeEditor();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'&&!$('editorDialog').open){e.preventDefault();$('search').focus();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='n'&&!$('editorDialog').open){e.preventDefault();openEditor();}});window.addEventListener('beforeunload',e=>{if($('editorDialog').open&&state.draftId&&state.editRevision>state.lastSavedRevision){writeDraft().catch(()=>{});e.preventDefault();e.returnValue='';}});window.addEventListener('online',async()=>{if(!state.ready)return;await sync();await refreshStats();await loadList();});window.addEventListener('offline',()=>{state.online=false;connection();});
async function boot(){document.body.classList.toggle('dark',localStorage.getItem('knowledge_base_theme')==='dark');let vaultId=localStorage.getItem('kb-vault-id');try{const health=await api('/api/health');if(health.version!=='2.3.3')throw new Error('当前地址是旧版服务，请使用新版启动入口。');vaultId=health.vaultId;localStorage.setItem('kb-vault-id',vaultId);}catch(error){if(error.status===401)return;if(!vaultId){$('records').innerHTML='<div class="empty"><h2>暂时无法连接资料库</h2><p>请运行项目里的启动脚本，再刷新此页。</p><button data-action="sync">重试连接</button></div>';return;}}try{await Store.open(vaultId);state.ready=true;await sync();await refreshStats();await loadList();await draftBanner();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});}catch(e){$('records').innerHTML=`<div class="empty"><h2>本地存储不可用</h2><p>${esc(e.message)}。请检查浏览器存储权限和磁盘空间。</p></div>`;}}
editorDialog.append(resizeHandle);
setInterval(async()=>{if(!state.ready||document.hidden||state.saving)return;try{await api('/api/health');await sync();}catch{}},30000);boot();
